PUBLIC BRIEF: {"buyer":"Paradigm Initiative","exclusions":["This is an employment-role normalization, not authorization to replace a hire or perform commissioned consulting work; no application, hiring decision or external outreach is authorized.","Website/social accounts, internal calendars, communications policies, approved response guidelines, organizational source content and private analytics were not supplied.","Experimental agent_draft annotations cover only proposed content, plans or research briefs; no live posting, autonomous ongoing monitoring, advertising spend or guaranteed media/engagement outcome is authorized."],"id":"paradigm-initiative-bilingual-communications-assistant-2025","requirements":[{"brick":"draft","id":"R1","owner":"blocked_private_input","text":"Help draft press releases and statements, circulate them to PIN's media network and publish them on its website when due."},{"brick":"plan","id":"R2","owner":"agent_draft","text":"Assist in developing communications and social-media plans."},{"brick":"plan","id":"R3","owner":"human_required","text":"Support execution of communications strategies in collaboration with the communications team, other departments and stakeholders."},{"brick":"draft","id":"R4","owner":"agent_draft","text":"Create engaging English- and French-language content for PIN's social-media channels."},{"brick":"transform","id":"R5","owner":"blocked_private_input","text":"Translate organizational content between French and English."},{"brick":"monitor","id":"R6","owner":"agent_draft","text":"Support media monitoring and track news relevant to PIN's work."},{"brick":"notify","id":"R7","owner":"blocked_private_input","text":"Under the Officer's direction, schedule and publish daily posts on Twitter, LinkedIn, Facebook, Instagram and TikTok, following the communications/social calendars, stated entry deadlines and communications policy."},{"brick":"monitor","id":"R8","owner":"blocked_private_input","text":"Monitor social comments