PUBLIC BRIEF: {"buyer":"Morrow County, Oregon","exclusions":["County facility records, detailed site information, staff input, professional surveys, and actual time/expense records were not supplied.","Additional facilities and outreach may be needed; the two principal buildings are not asserted to exhaust the scope. No construction award, fixed project budget, or fixed hourly workload is inferred.","Experimental boundary: no buyer contact, bid submission, spending, private-system access, or autonomous delivery of the engagement."],"id":"morrow-county-facility-project-management-2017","requirements":[{"brick":"plan","id":"R1","owner":"human_required","text":"Assess facility needs and help develop new-construction or remodeling plans, initially considering the approximately 2,800-square-foot Irrigon Annex and 4,000-square-foot Boardman Clinic and the preliminary 22-plus-employee accommodation estimate."},{"brick":"validate","id":"R2","owner":"human_required","text":"Advise on capacity, siting, and compliance with planning and development requirements, BOLI rules, DEQ requirements, building codes, and other applicable obligations."},{"brick":"report","id":"R3","owner":"blocked_private_input","text":"Combine County staff material with additional data, analyze needs, and prepare a focused needs proposal for Board of Commissioners review and approval."},{"brick":"plan","id":"R4","owner":"human_required","text":"Develop facility options and associated cost estimates, supporting public outreach throughout option development and evaluation."},{"brick":"plan","id":"R5","owner":"human_required","text":"Organize and manage public-input meetings, including at least three meetings: one each in Irrigon, Boardman, and Heppner."},{"brick":"report","id":"R6","owner":"blocked_private_input","text":"Maintain accurate records of project time, travel time, and other expenses, supporting cost and expense control."}],"source_url":"https://www.morrowcountyor.gov/sites/default/files/fileatt