PUBLIC BRIEF: {"buyer":"Paradigm Initiative","exclusions":["This normalizes an employment role; it does not authorize recruitment, applications, acting as an employee or selling the duties as a consulting engagement.","Partner databases, community updates, dashboards, internal records, calendars, invoices and finance systems were not supplied; no private-system updates or external distribution is authorized.","Experimental drafts are proposed research or document drafts only; agreement approval, negotiation, payments, travel bookings and event delivery remain with authorized humans."],"id":"paradigm-initiative-bilingual-partnerships-engagement-assistant-2025","requirements":[{"brick":"extract","id":"R1","owner":"blocked_private_input","text":"Gather community-team updates for the Net Rights Coalition."},{"brick":"monitor","id":"R2","owner":"blocked_private_input","text":"Maintain unit monitoring and stakeholder dashboards, update them every Friday and flag critical issues for immediate response."},{"brick":"reconcile","id":"R3","owner":"blocked_private_input","text":"Maintain accurate partner/stakeholder contacts and interaction histories, with quarterly verified-contact updates and database-quality reviews."},{"brick":"draft","id":"R4","owner":"agent_draft","text":"Draft, format and proofread partnership agreements, concept notes and memoranda of understanding for senior-staff review within three working days of request."},{"brick":"report","id":"R5","owner":"blocked_private_input","text":"Coordinate partner meetings, agendas, minutes and action follow-up with the P&E Officer, meeting the stated 24-hour scheduling/minutes target."},{"brick":"retrieve","id":"R6","owner":"agent_draft","text":"Conduct preliminary research on prospective partners, institutions and donors relevant to PIN's digital-rights and inclusion work."},{"brick":"reconcile","id":"R7","owner":"blocked_private_input","text":"Keep unit folders updated for accessible sharing."},{"brick":"retrieve","id":"R8","owner":"agent_draft","text":"Assist with research for digital-advocacy briefs."},{"brick":"plan","id":"R9","owner":"human_required","text":"Provide planning, logistical and administrative support for PIN engagements, particularly the Digital Rights and Inclusion Forum and other events."},{"brick":"plan","id":"R10","owner":"human_required","text":"Coordinate event invitations, RSVPs, venue bookings, travel and materials; send invitations three weeks ahead, confirm logistics one week ahead and process travel seven working days before events."},{"brick":"plan","id":"R11","owner":"human_required","text":"Support PIN's participation at external conferences and workshops through registrations and logistical arrangements."},{"brick":"report","id":"R12","owner":"blocked_private_input","text":"Compile data and documentation for partnership and engagement reports."},{"brick":"reconcile","id":"R13","owner":"blocked_private_input","text":"File, scan and archive partnership and engagement records, agreements and reports, filing partnership records within 48 hours of execution."},{"brick":"notify","id":"R14","owner":"blocked_private_input","text":"Distribute publications and research outputs to partners and stakeholders within two working days."},{"brick":"plan","id":"R15","owner":"blocked_private_input","text":"Maintain shared unit calendars daily and coordinate team schedules."},{"brick":"reconcile","id":"R16","owner":"blocked_private_input","text":"Process partnership invoices within five working days and coordinate payment schedules with finance."},{"brick":"monitor","id":"R17","owner":"blocked_private_input","text":"Maintain completion/deadline logs, meet weekly assigned deadlines, participate in weekly P&E Officer check-ins, submit accurate weekly timesheets and promptly update Smartsheet."}],"source_url":"https://paradigmhq.org/working-zone/vacancy-partnerships-and-engagements-assistant/","summary":"Historical full-time, hybrid English/French partnerships-and-engagement assistant job posting, not an outsourced RFP. The role supports partner research, records, agreements, DRIF and other events, communications and administration in the listed African locations. Applications closed November 12, 2025, with earlier filling possible.","title":"Vacancy: Bilingual Partnerships and Engagement Assistant"}
